'use strict';
let accountUser=null,accountCsrf='',accountRevision=0,accountReady=false,accountBackend=true;
let savePending=false,saveInFlight=false,saveBlocked=false,saveSequence=0;
const initialState=()=>({profile:{},records:[],meds:[],appointments:[],questions:[],symptoms:[],wellness:[],movements:[],contractions:[],postpartumLogs:[],bag:['Medical notes and ID','Phone and charger','Comfortable clothes','Toiletries','Maternity pads','Baby clothes and nappies'].map((text,i)=>({id:'bag-'+i,text,done:false})),birthPlan:{},mode:'pregnancy',notificationEnabled:false});
async function api(path,method='GET',body){let r=await fetch('/api/'+path,{method,credentials:'same-origin',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(accountCsrf?{'X-CSRF-Token':accountCsrf}:{})},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{throw Error('Account backend unavailable. Open the accounts preview at http://localhost:8081.')}if(!r.ok){let e=Error(data.error||'Request failed');e.status=r.status;throw e}return data}
function syncLabel(text){let el=$('#syncStatus');if(el)el.textContent=text}
function accountSave(){if(!accountUser||saveBlocked){syncLabel('Not saved — sign in or resolve the conflict');return false}savePending=true;saveSequence++;syncLabel('Saving…');void flushAccount();return true}
async function flushAccount(){if(saveInFlight||saveBlocked||!accountUser)return;saveInFlight=true;while(savePending&&!saveBlocked&&accountUser){savePending=false;let snap=JSON.parse(JSON.stringify(state));try{let result=await api('state','PUT',{state:snap,revision:accountRevision});accountRevision=result.revision;if(!savePending)syncLabel('Saved to your account')}catch(e){savePending=true;saveBlocked=true;syncLabel('Not saved');notify(e.message+' Your current edits remain in memory. Export them before reloading.');if($('#syncActions'))$('#syncActions').hidden=false;break}}saveInFlight=false}
function accountHeader(){let el=$('#accountControls');if(!el){el=document.createElement('div');el.id='accountControls';$('header').prepend(el)}el.innerHTML=accountUser?`<span>${esc(accountUser.email)}</span><small id="syncStatus">Saved to your account</small><button class="secondary" id="signout">Sign out</button><div id="syncActions" hidden><button id="retrySave">Retry save</button><button id="unsavedExport">Export current records</button></div>`:'<span>Bloom accounts</span>';let reportButton=$('#report');if(reportButton)reportButton.hidden=!accountUser;$('#nav').hidden=!accountUser;$('.aside-bottom').innerHTML='<p>Account records are stored by the local backend on this computer. No caregiver sharing.</p>'}
function accountGate(){accountHeader();return heading(accountBackend?'Your private pregnancy journal':'Start the account backend',accountBackend?'Sign in to access your own saved records.':'This page needs the local account server.')+(!accountBackend?card('Backend unavailable','<p>Start the server using the project instructions, then open <a href="http://localhost:8081">the accounts preview</a>.</p>'):`<div class="grid">${card('Sign in',form('loginForm',`<p>${field('loginEmail','Email address','email','','required autocomplete="username"')}</p><p>${field('loginPassword','Password','password','','required minlength="12" maxlength="256" autocomplete="current-password"')}</p>`,'Sign in'))}${card('Create an account',form('registerForm',`<p>${field('registerEmail','Email address','email','','required autocomplete="username"')}</p><p>${field('registerPassword','Choose a password','password','','required minlength="12" maxlength="256" autocomplete="new-password"')}</p><p class="muted">At least 12 characters. This local development account has no email verification or password recovery yet. Use a unique test password.</p>`,'Create account'))}</div><p class="muted">This is a local development version. The database is on this computer, not in the cloud. Use fictional health information.</p>`)}
async function loadAccount(){let data=await api('state');state={...initialState(),...data.state};accountRevision=data.revision;ensureExtras();savePending=false;saveBlocked=false;saveSequence=0;render();accountHeader()}
const settingsBeforeAccounts=renderers.settings;
renderers.settings=()=>settingsBeforeAccounts()+card('Account storage',`<p>Signed in as <b>${esc(accountUser?.email)}</b>. Journal data is saved in an encrypted SQLite database on the computer running the backend.</p><p>No health records are saved to browser local storage. Account synchronization works with this running server; cloud hosting and backups are not configured.</p><p>To retrieve the earlier prototype’s records, open <a href="http://localhost:8080/legacy-export.html" target="_blank" rel="noopener">Export earlier browser records</a>. Import a previously exported Bloom JSON file. Import replaces this account’s current journal after confirmation.</p><label for="importRecords">Choose a Bloom export</label><input id="importRecords" type="file" accept="application/json,.json"><p><button id="accountDelete" class="danger">Delete account</button></p>`);
async function logOut(){if(savePending||saveInFlight){notify('Wait for saving to finish. Resolve any save error before signing out.');return}try{await api('logout','POST');accountUser=null;accountCsrf='';state=initialState();ensureExtras();saveBlocked=false;savePending=false;alerted.clear();sentAlerts.clear();render();accountHeader();notify('Signed out.')}catch(e){notify(e.message)}}
document.addEventListener('submit',async e=>{if(!['loginForm','registerForm'].includes(e.target.id))return;e.preventDefault();let isRegister=e.target.id==='registerForm',v=vals(e.target),b=e.target.querySelector('button');b.disabled=true;try{let result=await api(isRegister?'register':'login','POST',{email:v[isRegister?'registerEmail':'loginEmail'],password:v[isRegister?'registerPassword':'loginPassword']});accountUser=result.user;accountCsrf=result.csrf;await loadAccount();notify(isRegister?'Account created. Your journal starts empty.':'Signed in. Your saved journal is loaded.')}catch(err){notify(err.message);b.disabled=false}});
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='signout')await logOut();if(b.id==='retrySave'){saveBlocked=false;void flushAccount()}if(b.id==='unsavedExport')download('bloom-unsaved-records.json',JSON.stringify(state,null,2),'application/json');if(b.id==='accountDelete'){if(savePending||saveInFlight){notify('Finish saving before deleting your account.');return}let pw=prompt('Enter your account password to permanently delete this account and its records.');if(pw===null)return;if(!confirm('Permanently delete this account and all its saved health records?'))return;try{await api('account','DELETE',{password:pw});accountUser=null;accountCsrf='';state=initialState();ensureExtras();render();accountHeader();notify('Account and records deleted from the current database.')}catch(err){notify(err.message)}}});
document.addEventListener('change',async e=>{if(e.target.id!=='importRecords')return;let f=e.target.files[0];if(!f)return;try{if(f.size>1_900_000)throw Error('Import file is too large.');let data=JSON.parse(await f.text());if(!data||typeof data!=='object'||Array.isArray(data)||!data.profile||typeof data.profile!=='object')throw Error('Choose a valid Bloom JSON export.');for(let k of ['records','meds','appointments','questions','symptoms','wellness','movements','contractions','postpartumLogs','bag'])if(data[k]!==undefined&&(!Array.isArray(data[k])||data[k].some(x=>!x||typeof x!=='object'||Array.isArray(x))))throw Error('Invalid journal records.');if(!confirm('Replace this account’s journal with the selected export?'))return;let clean=initialState();for(let k of Object.keys(clean).concat(['birthDate','activeContraction']))if(data[k]!==undefined)clean[k]=data[k];state=clean;ensureExtras();accountSave();render();notify('Import queued for account storage. Check the save status.')}catch(err){notify(err.message)}});
// Block journal actions before authentication. Public auth forms remain available.
document.addEventListener('submit',e=>{if(!accountUser&&!['loginForm','registerForm'].includes(e.target.id)){e.preventDefault();e.stopImmediatePropagation();notify('Sign in first.')}},true);
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!accountUser&&b&&!['loginForm','registerForm'].includes(b.closest('form')?.id)){e.stopImmediatePropagation();e.preventDefault()}},true);
window.addEventListener('beforeunload',e=>{if(savePending||saveInFlight){e.preventDefault();e.returnValue=''}});
(async()=>{try{await api('health');try{let session=await api('session');accountUser=session.user;accountCsrf=session.csrf;await loadAccount()}catch(e){if(e.status!==401)throw e}}catch(e){accountBackend=false}finally{accountReady=true;render();accountHeader()}})();
